// Criativo "fala + obras" no estilo da referência (Reels felipemustafanunes): o falante em tela cheia no próprio ambiente,
// título fixo amarelo no alto, frase branca logo abaixo do queixo, e obras de arte (pinturas, gravuras, colagens) aparecendo
// como cartões soltos ao redor dele, de 1 a 3 por bloco, trocando a cada assunto. Entradas secas (sem zoom/bounce).
import React from "react";
import { AbsoluteFill, Img, OffthreadVideo, Sequence, spring, staticFile, useCurrentFrame, useVideoConfig } from "remotion";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";
import { loadFont as loadSerif } from "@remotion/google-fonts/Cormorant";

const { fontFamily: SANS } = loadGeist("normal", { weights: ["600", "700"], subsets: ["latin"] });
const { fontFamily: MONO } = loadMono("normal", { weights: ["400"], subsets: ["latin"] });
const { fontFamily: SERIF } = loadSerif("italic", { weights: ["500"], subsets: ["latin"] });

type Slot = { x: number; y: number; w: number; h: number };
type Card = { src: string; slot: string; at: number; until: number };
type Line = { t: string; s: number; e: number };
export type TalkArtData = {
  width: number; height: number; fps: number; durationSec: number;
  video: string; talkEnd: number; title: string; titleY: number; captionY: number;
  slots: Record<string, Slot>; cards: Card[]; lines: Line[]; full: [number, number][];
  end: { at: number };
};
const S = (s: number, fps: number) => Math.round(s * fps);
const Mask: React.FC<{ at: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ at, children, style }) => {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  const k = spring({ frame: f - at, fps, config: { damping: 200 }, durationInFrames: 8 });
  return (
    <div style={{ overflow: "hidden", paddingBottom: "0.1em", ...style }}>
      <div style={{ transform: `translateY(${(1 - k) * 110}%)` }}>{children}</div>
    </div>
  );
};
const P = [".......", "##...##", "###.###", ".#####.", "...#...", "...#...", ".#####."];
const Broto: React.FC<{ size: number; start: number }> = ({ size, start }) => {
  const f = useCurrentFrame();
  const { fps } = useVideoConfig();
  let k = 0;
  const rects: React.ReactNode[] = [];
  P.forEach((row, y) =>
    [...row].forEach((ch, x) => {
      if (ch !== "#") return;
      const s = spring({ frame: f - (start + (6 - y) * 2 + k++ * 0.4), fps, config: { damping: 14, stiffness: 170 } });
      rects.push(<rect key={`${x}-${y}`} x={x * 10 + 1} y={y * 10 + 1} width={8} height={8} rx={2.6} fill="#F5F5F3" opacity={Math.min(1, s)} style={{ transformBox: "fill-box", transformOrigin: "center", transform: `scale(${0.2 + 0.8 * s})` }} />);
    }),
  );
  return <svg viewBox="0 0 70 70" width={size} height={size}>{rects}</svg>;
};
const SHADOW = "0 2px 10px rgba(0,0,0,.75), 0 0 2px rgba(0,0,0,.9)";

export const TalkArt: React.FC<TalkArtData> = (d) => {
  const f = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const t = f / fps;
  const talking = t < d.talkEnd;
  const inFull = d.full.some(([a, b]) => t >= a && t < b);
  const line = d.lines.find((l) => t >= l.s && t < l.e);
  return (
    <AbsoluteFill style={{ backgroundColor: "#000" }}>
      <Sequence from={0} durationInFrames={S(d.talkEnd, fps)}>
        <OffthreadVideo src={staticFile(d.video)} muted style={{ width: "100%", height: "100%", objectFit: "cover" }} />
      </Sequence>
      {talking && !inFull &&
        d.cards.filter((c) => t >= c.at && t < c.until).map((c, i) => {
          const s = d.slots[c.slot];
          return (
            <div key={`${c.src}-${i}`} style={{ position: "absolute", left: s.x * width, top: s.y * height, width: s.w * width, height: s.h * height, display: "flex", alignItems: "flex-start", justifyContent: "center" }}>
              <Img src={staticFile(c.src)} style={{ maxWidth: "100%", maxHeight: "100%", objectFit: "contain", boxShadow: "0 10px 30px rgba(0,0,0,.35)" }} />
            </div>
          );
        })}
      {talking && (
        <div style={{ position: "absolute", left: 80, right: 80, top: d.titleY * height, textAlign: "center", fontFamily: SANS, fontWeight: 700, fontSize: 74, letterSpacing: "-0.015em", color: "#F5D547", textShadow: SHADOW }}>{d.title}</div>
      )}
      {talking && line && (
        <div style={{ position: "absolute", left: 120, right: 120, top: d.captionY * height, display: "flex", justifyContent: "center", textAlign: "center" }}>
          <div style={{ fontFamily: SANS, fontWeight: 600, fontSize: 42, lineHeight: 1.14, color: "#fff", textShadow: SHADOW, textWrap: "balance" as any }}>{line.t}</div>
        </div>
      )}
      {t >= d.end.at && (
        <AbsoluteFill style={{ alignItems: "center", justifyContent: "flex-start", flexDirection: "column", paddingTop: 300 }}>
          <Broto size={130} start={S(d.end.at, fps) + 1} />
          <Mask at={S(d.end.at, fps) + 8} style={{ marginTop: 16 }}>
            <div style={{ fontFamily: SERIF, fontStyle: "italic", fontWeight: 500, fontSize: 150, lineHeight: 0.95, letterSpacing: "-0.03em", color: "#F5F5F3" }}>Nova Safra</div>
          </Mask>
          <Mask at={S(d.end.at, fps) + 12} style={{ marginTop: 10 }}>
            <div style={{ fontFamily: MONO, fontSize: 30, letterSpacing: "0.04em", color: "rgba(245,245,243,.6)" }}>uma comunidade · 17/11 → 31/12</div>
          </Mask>
          <Mask at={S(d.end.at, fps) + 16} style={{ marginTop: 44 }}>
            <div style={{ fontFamily: SANS, fontWeight: 700, fontSize: 100, color: "#F5F5F3" }}>R$27</div>
          </Mask>
          <Mask at={S(d.end.at, fps) + 20} style={{ marginTop: 6 }}>
            <div style={{ fontFamily: SANS, fontWeight: 600, fontSize: 36, color: "#C9CACD", textTransform: "uppercase" }}>preço único até 31/12</div>
          </Mask>
          <Mask at={S(d.end.at, fps) + 24} style={{ marginTop: 30 }}>
            <span style={{ display: "inline-block", border: "2px solid rgba(255,255,255,.25)", borderRadius: 999, padding: "14px 30px", fontFamily: SANS, fontWeight: 600, fontSize: 30, color: "#D6D7D9", textTransform: "uppercase" }}>7 dias de garantia</span>
          </Mask>
          <Mask at={S(d.end.at, fps) + 28} style={{ marginTop: 40 }}>
            <div style={{ background: "#F4F4F2", color: "#0B0C0D", borderRadius: 999, padding: "24px 54px", fontFamily: SANS, fontWeight: 700, fontSize: 40, textTransform: "uppercase" }}>Clique no link</div>
          </Mask>
        </AbsoluteFill>
      )}
    </AbsoluteFill>
  );
};

